mapper.select:
SELECT ROW_NUMBER() OVER (ORDER BY F.FLAG4 ) AS RNUM ,F.* FROM ( SELECT D.CRM_CODE ,D.CUST_KOR_NAME ,D.CUST_ADDRESS ,D.DEAL_CODE ,D.DEAL_CODE_NAME ,(SELECT Z.BASE_CD_NM FROM KYERP.TB_CM_CODE_DTL Z WHERE Z.BASE_CD_GRP = 'CM0030' AND Z.BASE_CD = D.CONTRACT_KIND) AS ITEM_NM ,D.MTAC_START_DT ,D.MTAC_END_DT ,D.HIS_TREAT_CODE ,D.HIS_TREAT_CODE_NM ,D.FLAG1 ,D.FLAG2 ,'C001' AS BILL_CODE ,CASE WHEN FLAG1 <> '0'AND FLAG2 <> '0' THEN TRUNC(FLAG2 / FLAG1*100) WHEN FLAG1 IS NULL AND FLAG2 IS NULL THEN NULL ELSE 0 END FLAG3 ,CASE WHEN TRUNC(SYSDATE) < TO_DATE(D.MTAC_END_DT, 'YYYYMMDD') --계약기간이 남았으면 THEN (TO_DATE(D.MTAC_END_DT, 'YYYYMMDD') - TO_DATE(D.MTAC_START_DT, 'YYYYMMDD') ) - (TRUNC(SYSDATE) - TO_DATE(D.MTAC_START_DT, 'YYYYMMDD')) WHEN FLAG1 IS NULL AND FLAG2 IS NULL THEN NULL ELSE 0 END FLAG4 FROM( SELECT A.CRM_CODE ,A.CUST_KOR_NAME ,SUBSTR(A.CUST_ADDRESS, 1, (INSTR(A.CUST_ADDRESS, ' ')-1)) CUST_ADDRESS ,B.DEAL_CODE --HIS 거래상태 ,(SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'CUST'AND Z.P_CODE = 'CD03' AND Z.CODE = B.DEAL_CODE)DEAL_CODE_NAME ,C.CONTRACT_KIND ,C.MAINT_ST_DATE AS MTAC_START_DT ,C.MAINT_END_DATE AS MTAC_END_DT ,B.HIS_TREAT_CODE ,(SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'CUST' AND Z.P_CODE = 'CD05' AND Z.CODE = B.HIS_TREAT_CODE) HIS_TREAT_CODE_NM ,TO_DATE(C.MAINT_END_DATE, 'YYYYMMDD') - TO_DATE(C.MAINT_ST_DATE, 'YYYYMMDD') FLAG1 ,CASE WHEN TRUNC(SYSDATE) < TO_DATE(C.MAINT_END_DATE, 'YYYYMMDD') THEN TRUNC(SYSDATE) - TO_DATE(C.MAINT_ST_DATE, 'YYYYMMDD') ELSE TO_DATE(C.MAINT_END_DATE, 'YYYYMMDD') - TO_DATE(C.MAINT_ST_DATE, 'YYYYMMDD') END FLAG2
FROM CRM_CUST_MGT A --Lineus 거래처 마스터 테이블 ,CRM_CUST_OPERATE_INFO B --Lineus 거래처 운영정보 테이블 ,KYERP.TB_SD_MAINT_MST C --ERP 무상계약 테이블 WHERE 1=1 AND A.SEQ = B.SEQ AND A.CUST_CODE = C.CUST_CODE(+) AND B.HIS_YN = 'Y' AND B.DEAL_CODE = #{search_type2}
)D )F ORDER BY FLAG4, FLAG3 DESC
